# -*- coding: utf-8 -*-
"""Residentado Médico 2020 · Anestesiología, preguntas 51-75"""
import lote08_base as B
L = []
MIL = "Gropper MA et al. Miller Anestesia, 10.ª ed. (Elsevier, 2024)"
MOR = "Morgan y Mikhail Anestesiología Clínica 6.ª ed. (2018)"
CHE = "Chestnut Obstetric Anesthesia 6.ª ed. (2020)"
GUY = "Guyton y Hall Tratado de Fisiología Médica 14.ª ed. (2021)"
def Q(n, tema, cat, c, f, nota=None, **kw): B.hacer(L, "ANESTESIOLOGIA", n, tema, cat, c, f, nota, **kw)

Q(51, "Reversión del bloqueo neuromuscular", "Relajantes musculares",
  'Los relajantes no despolarizantes bloquean de forma competitiva el receptor nicotínico de la placa motora. La neostigmina inhibe la acetilcolinesterasa, aumenta la acetilcolina en la unión neuromuscular y desplaza al relajante, de modo que restablece la transmisión; por eso es el fármaco clásico de reversión. Como también aumenta la acetilcolina en receptores muscarínicos, produce bradicardia, secreciones y broncoespasmo, y se asocia siempre con un antimuscarínico (atropina o glicopirrolato), que no revierte el bloqueo por sí solo. La naloxona antagoniza opioides, la piridoxina es una vitamina usada en toxicidad por isoniazida y la dexametasona es un corticoide con acción antiemética y antiinflamatoria; ninguna actúa en la placa motora. La guía de 2023 de la Sociedad Americana de Anestesiólogos sobre monitorización y antagonismo del bloqueo neuromuscular busca reducir el bloqueo residual, que se vigila con el tren de cuatro y se considera superado con una relación mayor o igual a 0,9. Una revisión sistemática de 2025 (35 ensayos, 4275 pacientes) mostró que el sugammadex, que encapsula al rocuronio y al vecuronio, logra esa relación más rápido que la neostigmina y reduce el bloqueo residual; en cambio, la neostigmina tiene techo de efecto y no sirve en bloqueo profundo. Perla: no se revierte un bloqueo intenso con neostigmina; hay que esperar la reaparición de al menos dos respuestas del tren de cuatro.',
  "Thilen SR et al. Anesthesiology 2023;138:13-41 (guía ASA de monitorización y antagonismo del bloqueo neuromuscular; solo resumen); Zhu N et al. Biomol Biomed 2025;26:295-306 (metaanálisis sugammadex frente a neostigmina; texto completo); Radkowski P et al. Med Sci Monit 2026;32:e951845 (revisión de relajantes no despolarizantes; texto completo); " + MIL)

Q(52, "Causas de retraso del vaciamiento gástrico", "Fisiología y riesgo de aspiración",
  'El vaciamiento gástrico depende del tono vagal, de la motilidad antral y de la coordinación pilórica, y se retrasa cuando predomina el tono simpático. El dolor, la ansiedad y el estrés activan el simpático y enlentecen el vaciamiento, de modo que un paciente traumatizado o con abdomen agudo debe considerarse con estómago lleno aunque haya ayunado. Esa es la causa patológica ofrecida entre las opciones. Los opiáceos, los antidepresivos tricíclicos (efecto anticolinérgico) y la dopamina retrasan también la motilidad, pero son causas farmacológicas y no una condición patológica; el embarazo es una situación fisiológica, con retraso real solo durante el trabajo de parto, sobre todo si se asocia con dolor o analgesia opioide. Una revisión de 2024 sobre los agonistas del receptor de GLP-1 señala como factores asociados con retraso del vaciamiento gástrico, además de esos fármacos, la diabetes, la enfermedad gastrointestinal, el dolor y el estado físico ASA elevado. Por eso, en el trauma, la urgencia abdominal, la obesidad, la diabetes con neuropatía y la gestación a término se aplica inducción de secuencia rápida con protección de la vía aérea. La guía ASA de ayuno de 2023 complementa las pautas de 2017 con líquidos con carbohidratos, goma de mascar y ayuno pediátrico, y recuerda que el ayuno no garantiza vacuidad gástrica. Perla: el dolor y el trauma anulan el ayuno; trate al paciente como de estómago lleno.',
  "Chang MG et al. J Clin Med 2024;13:6336 (agonistas GLP-1, contenido gástrico y aspiración; texto completo); Joshi GP et al. Anesthesiology 2023;138:132-151 (guía ASA de ayuno preoperatorio, actualización modular; solo resumen); " + MIL)

Q(53, "Contraindicación absoluta de la anestesia peridural", "Anestesia regional",
  'La anestesia peridural coloca anestésico local en el espacio epidural, donde hay un plexo venoso abundante, y la aguja o el catéter pueden lesionarlo. Un hematoma epidural espinal es raro, pero devastador, porque comprime la médula y exige descompresión en pocas horas; por eso las contraindicaciones absolutas son la coagulopatía o los trastornos de la hemostasia no corregidos, la anticoagulación fuera de los intervalos de seguridad, la infección en el sitio de punción o la bacteriemia, la hipertensión intracraneal con riesgo de herniación, la negativa del paciente y la hipovolemia grave no corregida. La guía de la Sociedad Americana de Anestesia Regional de 2025 (quinta edición) mantiene un criterio «antihemorrágico» y propone intervalos conservadores entre la última dosis del fármaco y el bloqueo neuroaxial, y entre este y la reanudación del tratamiento. En gestantes con preeclampsia, el consenso aceptado es que un recuento plaquetario superior a 70-80 x 10^9/L permite el bloqueo regional, según la revisión de Laskowska (2023). La analgesia postoperatoria, la cirugía urológica, la cirugía vascular y la analgesia postraumática son, en cambio, indicaciones frecuentes de la técnica, siempre que la hemostasia sea normal. Perla: antes de colocar o retirar un catéter epidural, revise los fármacos antitrombóticos y el recuento de plaquetas; pregunte por déficit motor nuevo después.',
  "Kopp SL et al. Reg Anesth Pain Med 2025, doi:10.1136/rapm-2024-105766 (ASRA, guía basada en evidencia, 5.ª ed.; solo resumen); Laskowska M et al. Med Sci Monit 2023;29:e941709 (eclampsia, anestesia y recuento plaquetario; texto completo); " + MIL)

Q(54, "Antagonistas 5-HT3 en náuseas y vómitos postoperatorios", "Antieméticos",
  'Las náuseas y los vómitos postoperatorios se desencadenan por la activación de la zona gatillo quimiorreceptora y del núcleo del tracto solitario, donde participan receptores de serotonina 5-HT3, dopamina D2, histamina H1, muscarínicos y de neurocinina 1. El ondansetrón es un antagonista selectivo del receptor 5-HT3, tanto en el sistema nervioso central como en las terminaciones vagales del tubo digestivo, y es la profilaxis de referencia por su eficacia y la escasez de sedación. La metoclopramida bloquea receptores D2 y favorece la motilidad gástrica; la trimetobenzamida es un antiemético con acción antidopaminérgica y antihistamínica; la cisaprida es un procinético agonista 5-HT4 que se retiró por prolongar el intervalo QT; y la dexametasona es un corticoide de acción antiinflamatoria y central menos precisa. Un metaanálisis en red de 2025 sobre cirugía ginecológica encontró que el palonosetrón fue superior al ondansetrón para varios desenlaces de náuseas y vómitos, y que el granisetrón fue la alternativa más eficaz. El ondansetrón puede alargar el intervalo QT y causar cefalea o estreñimiento. La quinta guía de consenso de 2026 mantiene la profilaxis multimodal según el riesgo del paciente. Perla: si el paciente ya recibió ondansetrón, no repita la misma clase en las primeras 6 horas; use otro mecanismo.',
  "Xu H et al. Int J Gynaecol Obstet 2025;171:177-189 (metaanálisis en red de antagonistas 5-HT3 en cirugía ginecológica; texto completo); Gan TJ et al. Anesth Analg 2026;143:497-513 (quinta guía de consenso sobre náuseas y vómitos postoperatorios, resumen ejecutivo; no se pudo leer su contenido); " + MIL)

Q(55, "Anestesia general en cesárea por enfermedad hipertensiva", "Anestesia obstétrica",
  'La gestante con preeclampsia o eclampsia tiene la vía aérea de riesgo: el edema laríngeo y faríngeo reduce el calibre, la intubación es más difícil, y el estómago está lleno por el retraso del vaciamiento y la incompetencia del esfínter esofágico inferior. Por eso la complicación característica de la anestesia general en una cesárea es la aspiración pulmonar del contenido gástrico (síndrome de Mendelson), junto con la intubación fallida. Además, la laringoscopia provoca una respuesta hipertensiva intensa que puede causar hemorragia intracraneal, edema pulmonar o desprendimiento de placenta. La revisión de Laskowska (2023) señala que la anestesia general aumenta el riesgo de aspiración y de intentos fallidos de intubación en estas pacientes, y la revisión de Dennis (2025) recomienda preferir la técnica neuraxial siempre que no haya contraindicación y, si hay que usar anestesia general, atenuar la respuesta presora. Las convulsiones corresponden a la enfermedad (eclampsia) y se previenen y tratan con sulfato de magnesio, no son complicación de la técnica; la cefalea pospunción y la retención urinaria son propias de la anestesia neuroaxial; la analgesia inadecuada ocurre en la anestesia regional insuficiente. Perla: ante una preeclampsia grave que necesita anestesia general, prepare videolaringoscopio, tubo más pequeño, secuencia rápida y un fármaco para atenuar la respuesta presora.',
  "Dennis AT et al. Anesthesiology 2025;142:378-402 (manejo perioperatorio de la preeclampsia; solo resumen); Laskowska M et al. Med Sci Monit 2023;29:e941709 (eclampsia, vía aérea y elección de anestesia; texto completo); " + CHE)

Q(56, "Relajante con liberación de histamina", "Relajantes musculares",
  'La liberación de histamina por los relajantes musculares es un efecto directo sobre mastocitos, dependiente de dosis y velocidad de inyección, que produce eritema, hipotensión, taquicardia y, a veces, broncoespasmo. Los aminoesteroides (vecuronio, rocuronio, pancuronio) liberan muy poca histamina y son los preferidos en el paciente alérgico o asmático; los bencilisoquinolínicos clásicos (atracurio, mivacurio, tubocurarina) son los más liberadores, y el cisatracurio apenas lo hace. La succinilcolina, único despolarizante de uso habitual, es la opción marcada, porque puede liberar histamina, además de provocar fasciculaciones, hiperpotasemia, bradicardia, aumento de la presión intraocular y, rara vez, hipertermia maligna. Además, junto con el rocuronio, es el relajante más implicado en la anafilaxia perioperatoria: en la encuesta francesa GERAP de 2017-2018, los bloqueadores neuromusculares fueron la primera causa, con 7,1 reacciones por 100 000 viales para la suxametonio y 5,6 para el rocuronio. La dexametonio (decametonio) y el flaxedil (galamina) son relajantes históricos sin uso actual. Perla: ante hipotensión, broncoespasmo y eritema tras inducir, sospeche anafilaxia al relajante, trate con adrenalina y derive para pruebas alérgicas.',
  "Tacquard C et al. Br J Anaesth 2024;132:1230-1237 (encuesta GERAP, anafilaxia perioperatoria en Francia; texto completo); Radkowski P et al. Med Sci Monit 2026;32:e951845 (relajantes no despolarizantes y efectos de la succinilcolina; texto completo); " + MIL,
  nota="La liberación clínicamente relevante de histamina es mayor con los bencilisoquinolínicos (atracurio, mivacurio) que con la succinilcolina; se mantiene la clave oficial porque de las opciones es el único relajante con ese efecto descrito, y es además el más ligado a anafilaxia.")

Q(57, "Hipnótico con mayor depresión que los barbitúricos", "Anestesia intravenosa",
  'El propofol es un alquilfenol que potencia el receptor GABA-A y, a dosis de inducción, produce una depresión cardiovascular y respiratoria más acentuada que el tiopental: baja la presión arterial por vasodilatación arterial y venosa y por menor contractilidad, atenúa el reflejo barorreceptor, deprime la ventilación hasta la apnea y suprime los reflejos de la vía aérea. Por eso se recomienda reducir la dosis en ancianos, hipovolémicos y pacientes ASA 3 y 4, e inyectarlo lentamente. El etomidato conserva la hemodinamia, aunque inhibe la 11-beta-hidroxilasa suprarrenal; el sevoflurano es un halogenado inhalatorio cuya inducción es suave y no se compara con el barbitúrico en este sentido; el fentanilo es un opioide analgésico que, aislado, no produce hipnosis fiable; y el midazolam es una benzodiazepina de efecto hemodinámico discreto, aunque potencia la depresión respiratoria de otros fármacos. Un ensayo multicéntrico de 2024 en pacientes ASA 3 y 4 mostró más episodios de hipotensión posinducción y más requerimiento de noradrenalina con propofol que con remimazolam. Perla: en el paciente inestable use dosis reducidas de propofol o prefiera etomidato o ketamina, y tenga vasopresor listo.',
  "Fechner J et al. Anaesthesia 2024;79:410-422 (ensayo multicéntrico de remimazolam frente a propofol en ASA 3 y 4; solo resumen); " + MIL + "; " + MOR,
  nota="La comparación del enunciado («más depresor que los barbitúricos») es discutible: el tiopental también deprime mucho la hemodinamia. Se mantiene la clave oficial (propofol).")

Q(58, "Vasodilatador humoral del flujo sanguíneo", "Fisiología cardiovascular",
  'El flujo local se regula por factores neurales, humorales y metabólicos. Entre los agentes humorales se distinguen los vasoconstrictores (noradrenalina, adrenalina en receptores alfa, angiotensina II, vasopresina, endotelina) y los vasodilatadores (bradicinina, histamina, prostaglandinas vasodilatadoras e iones como el potasio y el magnesio). La angiotensina II y la vasopresina producen una vasoconstricción potente y sostenida, y la noradrenalina eleva la resistencia periférica actuando sobre los receptores alfa-1. La adrenalina puede dilatar el lecho muscular por receptores beta-2, pero, en conjunto y a dosis altas, predomina la constricción. La serotonina es el agente que la clave identifica como vasodilatador en esta lista: actúa en receptores 5-HT del endotelio y del músculo liso, con efectos que dependen del lecho y del receptor, y participa en el enrojecimiento facial y la hipotensión de las crisis carcinoides. Una revisión de 2026 sobre el rubor lista a la serotonina entre los mediadores vasoactivos, junto con histamina, sustancia P, prostaglandinas y péptido intestinal vasoactivo. Hay que recordar que sobre las arterias lesionadas y las plaquetas activadas la serotonina produce vasoconstricción. Perla: ante rubor, diarrea y sibilancias, piense en síndrome carcinoide y mida el ácido 5-hidroxiindolacético urinario.',
  "García-Sáenz MR et al. Clin Endocrinol (Oxf) 2026;105:367-377 (rubor: mecanismos neuroendocrinos; texto completo); " + GUY,
  nota="La serotonina tiene efecto bifásico (vasodilatadora o vasoconstrictora según receptor y lecho vascular); se mantiene la clave oficial porque las demás opciones son vasoconstrictoras en la clasificación habitual.")

Q(59, "Coeficiente de partición del anestésico local", "Farmacología de anestésicos locales",
  'Las propiedades fisicoquímicas de un anestésico local determinan su comportamiento clínico: la liposolubilidad se relaciona con la potencia, la unión a proteínas con la duración y el pKa con la rapidez de inicio. El pKa es el pH en que la mitad de la molécula está ionizada; como los anestésicos locales son bases débiles, a pH 7,4 solo la fracción no ionizada atraviesa el epineuro y la membrana neuronal, y dentro del axón la fracción ionizada es la que bloquea el canal de sodio. El coeficiente de distribución aparente (partición) entre las fases lipídica y acuosa a pH fisiológico depende, por tanto, del pKa; un pKa cercano a 7,4 (lidocaína, 7,7) da más base libre y un inicio más rápido que uno alto (bupivacaína, 8,1). Un estudio de 2023 explica que la alcalinización con bicarbonato aumenta la proporción no ionizada y acelera el comienzo de la acción. El Ph de la solución modifica la fracción disponible, pero no es una propiedad del fármaco; la fijación a proteínas condiciona la duración; la dosis máxima es un límite de seguridad; y la liposolubilidad, estrictamente, se mide con el coeficiente de partición aceite-agua. Perla: en un tejido infectado el pH ácido deja menos base libre, y el bloqueo falla o se retrasa.',
  "Valiulla MUE et al. Cureus 2023;15:e37934 (anestésico local tamponado con bicarbonato, pKa y fracción no ionizada; texto completo); " + MIL + "; " + MOR,
  nota="En sentido estricto, el coeficiente de partición aceite-agua mide la liposolubilidad (opción E). La clave oficial marca el pKa, del que depende el coeficiente de distribución aparente a pH 7,4; se mantiene la clave oficial.")

Q(60, "Anestésico local del grupo éster", "Anestesia regional",
  'Los anestésicos locales se clasifican por el enlace que une el anillo aromático con la cadena amina: éster o amida. Los ésteres (cocaína, procaína, cloroprocaína, tetracaína, benzocaína) se hidrolizan en plasma por las pseudocolinesterasas, tienen vida media muy corta, y su metabolito, el ácido paraaminobenzoico, es el responsable de reacciones alérgicas. Las amidas (lidocaína, mepivacaína, prilocaína, bupivacaína, levobupivacaína, ropivacaína, etidocaína) se metabolizan en el hígado por el citocromo P450, y en su nombre llevan una «i» antes de «-caína»; casi nunca causan alergia verdadera. Entre las opciones, la cloroprocaína es el único éster; prilocaína, lidocaína, etidocaína y bupivacaína son amidas. La cloroprocaína tiene un inicio rápido y una duración breve, por lo que se emplea en cesárea urgente por vía epidural y en la anestesia espinal ambulatoria. Un reporte de 2026 describe una espinal con cloroprocaína al 1 % en una cesárea por preeclampsia, tras una historia sugestiva de alergia a las amidas, con bloqueo adecuado hasta T4 y recuperación en unos 70 minutos. Perla: la pseudocolinesterasa atípica prolonga el efecto de los ésteres, y la alergia a uno obliga a evitar los demás ésteres, no a las amidas.',
  "Ratanshi NA et al. Anaesth Rep 2026;14:e70063 (espinal con cloroprocaína 1 % en cesárea; solo resumen); Yu J et al. Front Pharmacol 2024;15:1432918 (lidocaína con bicarbonato frente a cloroprocaína epidural en cesárea; texto completo); " + MIL)

Q(61, "Prevención de la aspiración pulmonar", "Vía aérea y riesgo de aspiración",
  'La aspiración pulmonar del contenido gástrico durante la anestesia depende del volumen y la acidez del contenido, de la pérdida de reflejos y de la posición del paciente. La medida simple y eficaz que la clave identifica es la postura adecuada: la cabeza elevada o la posición semisentada reduce la regurgitación pasiva, y, en la gestante, el desplazamiento uterino lateral izquierdo mejora la posición. Las demás opciones son erróneas: el ayuno mínimo para la leche materna es de 4 horas y no de 1 hora, según las pautas ASA de 2017, y la actualización modular de 2023 se centró en los líquidos con carbohidratos, la goma de mascar y la duración del ayuno pediátrico; la presión cricoidea sigue siendo una maniobra discutida, pero no se contraindica en la inducción de secuencia rápida si se aplica bien y se retira cuando se complica la laringoscopia; se debe aspirar la sonda nasogástrica antes de la inducción en un paciente con obstrucción intestinal; y la preoxigenación busca una reserva de oxígeno, no una insuflación pulmonar forzada. Una revisión de 2024 sobre agonistas de GLP-1 recuerda que estos fármacos aumentan el contenido gástrico residual aunque haya ayuno. Perla: ante estómago lleno, elija secuencia rápida con cabeza elevada, aspiración gástrica previa y tubo con balón.',
  "Joshi GP et al. Anesthesiology 2023;138:132-151 (guía ASA de ayuno preoperatorio, actualización modular; solo resumen); Chang MG et al. J Clin Med 2024;13:6336 (GLP-1 y contenido gástrico; texto completo); " + MIL)

Q(62, "Fármacos que modifican la presión intraocular", "Anestesia oftalmológica",
  'La presión intraocular depende del equilibrio entre la producción del humor acuoso, su drenaje y la presión venosa epiescleral, y está influida por el tono de los músculos extraoculares, la presión arterial y el CO2. Los relajantes no despolarizantes (rocuronio, vecuronio, cisatracurio) relajan la musculatura extraocular y no elevan la presión intraocular, y por eso, en el contexto de la pregunta, son los fármacos que la disminuyen o la mantienen baja; los anestésicos intravenosos (propofol, tiopental) y los halogenados también la reducen. La succinilcolina la eleva transitoriamente por la contracción tónica de los músculos extraoculares y el aumento de la presión venosa; una revisión de 2026 enumera, entre sus efectos adversos, la hiperpotasemia, la bradicardia y el aumento de la presión intraocular. La ketamina puede elevarla ligeramente, aunque el dato es debatido; los corticoides la elevan con el uso prolongado, sobre todo en respondedores; y los ciclopléjicos (atropina, ciclopentolato) producen midriasis y pueden precipitar el cierre angular en ojos predispuestos. Un bloqueo tópico no controla la presión intraocular, según el capítulo de Mahan sobre anestesia regional ocular. Perla: en un ojo abierto, con riesgo de extrusión, evite la succinilcolina y asegure profundidad anestésica antes de laringoscopia.',
  "Radkowski P et al. Med Sci Monit 2026;32:e951845 (efectos adversos de la succinilcolina y relajantes no despolarizantes; texto completo); Mahan M et al. Local and Regional Anesthesia in Ophthalmology and Ocular Trauma. StatPearls 2023 (solo resumen); " + MIL)

Q(63, "Lesión dental durante la intubación y evento adverso", "Seguridad del paciente y ética",
  'La fractura de un diente durante la laringoscopia es una complicación conocida de la vía aérea difícil. La revisión sistemática de Neto (2023) señala que los incisivos centrales superiores son los más afectados, que el mal estado dental y la presión excesiva son factores contribuyentes, y que se trata de un problema con implicaciones legales. Por eso la conducta correcta es notificar y registrar el evento adverso, y explicar lo ocurrido al paciente o a sus familiares: la comunicación honesta es un deber ético, respeta la autonomía y la confianza, y reduce las demandas. Además, debe documentarse el estado dental previo en la valoración preanestésica, y buscar y retirar los fragmentos, porque pueden aspirarse y migrar a la vía aérea o al tubo digestivo; si no se recuperan, debe solicitarse una radiografía. Ocultar el hecho o no notificarlo es antiético y expone al paciente a complicaciones no tratadas y al profesional a una sanción mayor; continuar sin informar, entregar el diente solo a enfermería o despertar al paciente sin necesidad no resuelven nada. Se recomienda, tras la cirugía, derivar a odontología para reimplante o reparación. Perla: registre en la historia clínica el estado dental antes de intubar, con una nota breve y firmada.',
  "Neto JM et al. J Clin Med 2023;12:5343 (daño dental durante la anestesia general; texto completo); " + MIL + "; " + MOR)

Q(64, "Escopolamina como antiemético", "Antieméticos",
  'La escopolamina (hioscina) es un antagonista muscarínico que bloquea la transmisión colinérgica desde el sistema vestibular y el centro del vómito, y se emplea como parche transdérmico para prevenir náuseas postoperatorias y mareo del movimiento. Su efecto aparece entre 2 y 4 horas después de colocar el parche, de modo que se aplica la noche anterior o al menos 2-4 horas antes de que acabe la cirugía, como en este caso. Su bloqueo muscarínico explica los efectos adversos: boca seca, visión borrosa por midriasis y cicloplejía, taquicardia, retención urinaria, somnolencia y confusión. La paciente del enunciado presenta boca seca y trastornos visuales, lo que identifica a la escopolamina. El dimenhidrinato es un antihistamínico con cierta acción anticolinérgica, pero lo habitual es la sedación; el ondansetrón y el tropisetrón son antagonistas 5-HT3 que producen cefalea o estreñimiento, y la dexametasona puede causar hiperglucemia, no síntomas anticolinérgicos. Un estudio de cohorte de 2024 con más de 400 000 pacientes mostró que el uso perioperatorio de escopolamina se asoció con más delirio, neumonía y retención urinaria, sobre todo en mayores de 70 años. Perla: evite el parche de escopolamina en ancianos, en glaucoma de ángulo cerrado y en personas con retención urinaria.',
  "Sun G et al. BMC Anesthesiol 2024;24:438 (eventos adversos intrahospitalarios con escopolamina perioperatoria; texto completo); Gan TJ et al. Anesth Analg 2026;143:497-513 (quinta guía de consenso sobre náuseas y vómitos postoperatorios, resumen ejecutivo; no se pudo leer su contenido); " + MIL)

Q(65, "Causa de acidosis respiratoria aguda", "Equilibrio ácido-base",
  'La acidosis respiratoria aguda es el aumento rápido de la presión arterial de CO2 con descenso del pH, por hipoventilación alveolar: el riñón aún no ha compensado reteniendo bicarbonato, algo que tarda 3 a 5 días. Se debe a depresión central (opioides, sedantes, anestésicos), a debilidad neuromuscular, a obstrucción de la vía aérea o a una ventilación mecánica con un volumen minuto insuficiente. Entre las opciones, la ventilación mecánica inadecuada, es decir, un volumen minuto bajo o ajustes que permiten la hipercapnia, es la causa aguda que la clave señala. La EPOC produce una retención crónica de CO2 con pH casi normal por compensación renal, y solo se descompensa de forma aguda en las exacerbaciones; la miastenia y las lesiones medulares altas causan hipoventilación por falla del músculo respiratorio y pueden provocar acidosis aguda si hay crisis o lesión cervical, pero se interpretan como causas neuromusculares; y el broncoespasmo produce primero hiperventilación y alcalosis respiratoria, y retención solo en fases avanzadas. Una revisión de 2023 de los trastornos ácido-base en el paciente crítico divide las alteraciones en metabólicas y respiratorias y propone un abordaje sistemático. Perla: en un paciente ventilado, un CO2 elevado con pH bajo se corrige primero subiendo el volumen minuto, y descartando espacio muerto y broncoespasmo.',
  "Achanti A y Szerlip HM. Clin J Am Soc Nephrol 2023;18:102-112 (trastornos ácido-base en el paciente crítico; solo resumen); " + MIL,
  nota="La miastenia y la lesión espinal también pueden producir acidosis respiratoria aguda; se mantiene la clave oficial (ventilación mecánica, por hipoventilación iatrogénica) como la causa más directa de las opciones.")

Q(66, "Vasodilatación en la raquianestesia", "Anestesia regional",
  'La anestesia espinal bloquea las fibras simpáticas preganglionares (T1-L2), que son fibras B finas y mielínicas, y el bloqueo simpático alcanza dos a seis segmentos por encima del nivel sensitivo. Al desaparecer el tono simpático, las arteriolas y las vénulas se dilatan: la reducción de las resistencias vasculares sistémicas y el atrapamiento venoso con menor retorno disminuyen la presión arterial; si el bloqueo alcanza T1-T4, se pierde la aceleración cardiaca y aparece bradicardia. Por eso la clave es la reducción de las resistencias vasculares. Es falso que aumente la poscarga, que la presión arterial esté aumentada, que no haya bloqueo simpático o que aumente el gasto cardiaco, que más bien disminuye por menor precarga. En la gestante, la compresión aortocava agrava la hipotensión; las guías de la SOAP y de ERAS recomiendan el desplazamiento uterino y la prevención con vasopresor, y una carta científica de 2026 las menciona al comentar un ensayo sobre la elevación de piernas como maniobra para reducir la hipotensión poscesárea. La hipotensión se previene con precarga o cocarga de líquido y vasopresores, de preferencia fenilefrina o noradrenalina, y se trata con efedrina si hay bradicardia. Perla: la hipotensión tras la espinal en la cesárea se previene mejor con una infusión profiláctica de vasopresor que con la carga de líquidos.',
  "Piscopo M et al. J Anesth Analg Crit Care 2026, doi:10.1186/s44158-026-00410-x (hipotensión poscesárea tras bloqueo subaracnoideo; texto completo de una carta); Landau R et al. Am J Obstet Gynecol 2026;233:S135-S152 (anestesia neuroaxial para cesárea; solo resumen); " + MIL + "; " + CHE)

Q(67, "Antagonista de las benzodiazepinas", "Farmacología anestésica",
  'El flumazenil es una imidazobenzodiazepina que se une al sitio benzodiazepínico del receptor GABA-A sin actividad intrínseca y desplaza de forma competitiva a las benzodiazepinas, de modo que revierte la sedación, la amnesia y la depresión respiratoria. Se usa en la reversión de la sedación procedimental o de la anestesia general con benzodiazepinas y en la sobredosis, a dosis de 0,2 mg intravenosos repetidos hasta 1 mg. Su vida media corta (alrededor de una hora) es menor que la de la mayoría de las benzodiazepinas, por lo que puede reaparecer la sedación y exige vigilancia. Está contraindicado, o debe usarse con cuidado, en pacientes con dependencia crónica o con sobredosis mixta con antidepresivos tricíclicos, porque puede precipitar convulsiones o abstinencia. La naloxona antagoniza opioides, el amobarbital es un barbitúrico sedante, la melatonina regula el ritmo circadiano y la cafeína es un antagonista de adenosina con efecto estimulante limitado. Una revisión de 2025 sobre remimazolam recuerda que sus efectos pueden revertirse con flumazenil, y un metaanálisis citado en ella halló menos depresión respiratoria y menor tiempo de extubación con esa combinación. Perla: tras flumazenil, vigile al menos 2 horas por resedación, y úselo con cautela en epilépticos.',
  "Sharbaf Shoar N et al. Flumazenil. StatPearls 2024 (solo resumen); Aszkiełowicz A et al. Anaesthesiol Intensive Ther 2025;57:257-266 (revisión de remimazolam; texto completo); " + MIL)

Q(68, "Relajante menos indicado en cardiomiopatía", "Relajantes musculares",
  'En el paciente con cardiomiopatía se busca estabilidad hemodinámica, frecuencia cardiaca baja y un gasto cardiaco sin sobrecarga. El pancuronio, un aminoesteroide de acción prolongada, bloquea los receptores muscarínicos M2 del nodo sinusal e inhibe la recaptación de noradrenalina, lo que produce taquicardia, aumento de la presión arterial y del gasto cardiaco, y un mayor consumo miocárdico de oxígeno, efectos indeseables en la miocardiopatía, la isquemia y las arritmias. Por esa acción vagolítica es el menos indicado. El atracurio y el cisatracurio son bencilisoquinolinas que se degradan por eliminación de Hofmann y tienen un perfil cardiovascular estable (el atracurio libera algo de histamina con dosis altas); el vecuronio carece de efecto vagolítico significativo y es muy estable; y el mivacurio, de acción breve, libera histamina si se inyecta rápido. El pancuronio, además, tiene eliminación renal predominante, una duración larga y un riesgo de bloqueo residual que, según la revisión de Hunter (2024), exigió siempre monitorización cuantitativa. La ficha de StatPearls de 2023 señala que el pancuronio cayó en desuso por esa farmacocinética. Perla: con un corazón enfermo, prefiera cisatracurio o rocuronio y revierta con monitorización cuantitativa del bloqueo.',
  "Das GN et al. Pancuronium. StatPearls 2023 (solo resumen); Hunter JM. Br J Anaesth 2024;132:461-465 (dosis excesiva o insuficiente de relajantes y reversores; solo resumen); " + MIL)

Q(69, "Anestesia local para cesárea urgente", "Anestesia obstétrica",
  'Una cesárea urgente en una gestante estable se maneja de preferencia con anestesia neuroaxial, porque evita los riesgos de la vía aérea obstétrica (intubación difícil y aspiración) y reduce la exposición fetal a fármacos. La espinal es la técnica más rápida y fiable; entre las opciones, la bupivacaína al 0,5 % hiperbárica es el anestésico local recomendado: la glucosa lo vuelve más denso que el líquido cefalorraquídeo, de modo que el nivel del bloqueo se controla con la posición. Un ensayo de 2023 comparó 12,5 mg de bupivacaína isobárica con la misma dosis hiperbárica en cesárea electiva y concluyó que la hiperbárica da un inicio más rápido y mayor estabilidad hemodinámica. La lidocaína al 5 % se asoció con síntomas neurológicos transitorios y toxicidad, y ya no se usa por vía espinal; la ketamina con fentanilo y el propofol son componentes de una anestesia general o sedación, y el remifentanilo se reserva para atenuar la respuesta a la intubación o para un parto con contraindicación neuroaxial. Una revisión de 2026 sobre anestesia neuroaxial para cesárea resalta que la espinal ofrece el bloqueo más fiable y de inicio más rápido. Perla: reserve la anestesia general para el compromiso fetal inminente, la coagulopatía o el fracaso de la técnica regional.',
  "Besha A et al. J Pain Res 2023;16:3545-3558 (bupivacaína hiperbárica frente a isobárica en cesárea electiva; texto completo); Landau R et al. Am J Obstet Gynecol 2026;233:S135-S152 (anestesia neuroaxial y analgesia en cesárea; solo resumen); " + CHE)

Q(70, "Sustancia P en la transmisión del dolor", "Fisiología del dolor",
  'El dolor nociceptivo se transmite desde las fibras Adelta y C hasta el asta dorsal, donde las terminales presinápticas liberan neurotransmisores excitadores: glutamato, que genera la respuesta rápida por receptores AMPA, y neuropéptidos como la sustancia P y el péptido relacionado con el gen de la calcitonina (CGRP), que modulan la respuesta lenta y la sensibilización central. La sustancia P fue la primera identificada: von Euler y Gaddum la hallaron en 1931 en extractos de intestino y cerebro como un polvo que contraía el músculo liso y bajaba la presión arterial; Lembeck propuso en 1953 su papel como mediador del dolor, y Chang y Leeman la aislaron y secuenciaron en 1970 como un undecapéptido. Actúa sobre el receptor de neurocinina 1. La calmodulina es una proteína fijadora de calcio; el tromboxano es un eicosanoide proagregante; la interleucina 1 es una citocina proinflamatoria que sensibiliza al nociceptor; y la inmunoglobulina E interviene en la alergia. Una revisión de 2025 sobre señalización neuromoduladora en dolor crónico confirma que la sustancia P y el CGRP son neuropéptidos clave en la sensibilización periférica y central. Perla: a pesar de su papel, los antagonistas NK1 fracasaron como analgésicos y se usan sobre todo como antieméticos.',
  "Varrassi G et al. Cells 2025;14:1320 (señalización neuromoduladora en dolor crónico; texto completo); " + MIL + "; " + GUY,
  nota="El enunciado duda entre la sustancia primera descubierta y la primera activada; se mantiene la clave oficial (sustancia P), la primera identificada en la transmisión del dolor. El glutamato es el primer neurotransmisor que se activa en la sinapsis nociceptiva.")

Q(71, "Analgesia epidural e íleo posoperatorio", "Analgesia posoperatoria",
  'El íleo posoperatorio es la disfunción transitoria de la motilidad gastrointestinal tras una cirugía abdominal, sin obstrucción mecánica. Se origina en una fase neural precoz (reflejos simpáticos activados por el estímulo quirúrgico) y en una fase inflamatoria tardía, y se agrava con opioides, líquidos excesivos e inmovilidad. La analgesia epidural torácica con anestésico local bloquea los aferentes y eferentes simpáticos esplácnicos (T5-L1), deja predominar el parasimpático, mejora la perfusión esplácnica, disminuye la respuesta de estrés y permite ahorrar opioides; por eso acelera el retorno de la función intestinal en la cirugía abdominal abierta. Esa es la clave. No tiene efecto inflamatorio, no aumenta el dolor, y favorece la movilización más precoz, no la retarda. Una revisión de 2024 sobre el íleo tras cirugía colorrectal mínimamente invasiva consideró la epidural como el estándar en cirugía colorrectal abierta, pero concluyó que no es beneficiosa para prevenir el íleo en la cirugía mínimamente invasiva, por sus riesgos, y sugirió alternativas como el bloqueo del plano transverso del abdomen y la lidocaína intravenosa. Perla: la epidural torácica con anestésico local es útil en laparotomía mayor, pero en cirugía laparoscópica no justifica sus riesgos.',
  "Abernethy EK et al. Dig Surg 2024;41:79-91 (íleo posoperatorio tras cirugía colorrectal mínimamente invasiva; texto completo); " + MIL + "; " + MOR)

Q(72, "Bloqueo del nervio femorocutáneo", "Anestesia regional",
  'El nervio cutáneo femoral lateral (femorocutáneo) nace de L2-L3, cruza la pelvis por el borde lateral del psoas y sale bajo el ligamento inguinal, cerca de la espina ilíaca anterosuperior, para dar sensibilidad a la cara anterolateral del muslo. Es un nervio solo sensitivo. En la técnica clásica de puntos de referencia se hace un botón intradérmico a unos 2,5 cm por dentro y por debajo de la espina ilíaca anterosuperior, y se infiltra en abanico bajo la fascia lata; hoy se hace con ecografía, que aumenta la tasa de éxito. Una publicación de 2023 sobre el bloqueo del nervio femorocutáneo tras artroplastia de cadera lo describe como el nervio que da la sensibilidad del dolor de la parte externa del muslo, muy variable en su anatomía, y con una tasa de éxito históricamente baja que mejoró con ecografía. Sus indicaciones son la meralgia parestésica, la toma de injertos de piel del muslo y la analgesia del abordaje de cadera. El bloqueo crural (femoral) se hace 1 a 1,5 cm lateral a la arteria femoral, bajo el ligamento inguinal; el bloqueo del tobillo, de la rodilla y del tibial anterior corresponden a otros territorios. Perla: en la meralgia parestésica, el alivio con un bloqueo diagnóstico confirma el atrapamiento del nervio.',
  "Sakuraba S et al. Juntendo Iji Zasshi 2023;69:116-123 (bloqueo del nervio femorocutáneo lateral tras artroplastia de cadera; texto completo); " + MIL + "; " + MOR)

Q(73, "Descenso del CO2 espiratorio final", "Monitorización",
  'El CO2 espiratorio final (PETCO2) refleja la producción de CO2, su transporte al pulmón por el gasto cardiaco y la ventilación alveolar. Se reduce cuando la ventilación alveolar es excesiva (hiperventilación), cuando disminuye el gasto cardiaco o el flujo pulmonar (embolia, hipovolemia, paro) y cuando la producción cae (hipotermia, profundidad anestésica). La función inadecuada del respirador, es decir, un volumen minuto programado por encima de las necesidades, o ajustes que hiperventilan al paciente, es la causa técnica que la clave señala. En cambio, la cal sodada agotada permite la reinhalación de CO2 y lo eleva; un flujo de gas fresco escaso, en un circuito semicerrado, favorece la reinhalación si la cal está agotada; los fallos de las válvulas unidireccionales provocan reinhalación y elevación de la curva basal; y las fugas pueden alterar el muestreo, aunque su efecto principal es un volumen menor. Una revisión de 2023 sobre capnografía recuerda que este monitor detecta con rapidez las alteraciones respiratorias, circulatorias y metabólicas, es un estándar para confirmar la intubación y es esencial en toda sedación. Perla: una caída súbita de PETCO2 a cero, con la curva ausente, sugiere desconexión, intubación esofágica u obstrucción; un descenso gradual sugiere hiperventilación o bajo gasto.',
  "Wollner EA et al. Anesth Analg 2023;137:934-942 (capnografía, revisión narrativa; solo resumen); " + MIL + "; " + MOR,
  nota="Una fuga mantenida puede reducir también el PETCO2 medido; se mantiene la clave oficial (función inadecuada del respirador, con hiperventilación).")

Q(74, "Anestesia en gestante con cesárea previa", "Anestesia obstétrica",
  'En una gestante estable con cesárea anterior que acepta una prueba de trabajo de parto, la analgesia epidural es la técnica de elección. Permite una analgesia eficaz y continua, y, si surge una indicación de cesárea o una sospecha de rotura uterina, el catéter ya colocado se utiliza para extender el bloqueo a nivel quirúrgico, lo que evita una anestesia general con su riesgo de intubación fallida y aspiración. La preocupación de que la epidural enmascare la rotura uterina no se sostiene: una revisión de 2026 sobre rotura uterina indica que la analgesia epidural altera la percepción del dolor, pero casi nunca elimina por completo los signos clínicos, y que el aumento de los bolos requeridos puede avisar de un proceso en evolución, siendo la alteración de la frecuencia cardiaca fetal el signo más constante. La revisión de expertos de 2024 sobre trabajo de parto tras cesárea concluye que, con monitorización estrecha y un protocolo hospitalario, es seguro y debe ofrecerse a la mayoría de las pacientes con una cesárea previa de segmento transverso. La anestesia general, inhalatoria o intravenosa, y la caudal no son la elección. Perla: en la paciente con cesárea previa en trabajo de parto, un catéter epidural funcional y recurrir de inmediato a quirófano son parte del plan de seguridad.',
  "Opipari A et al. Curr Opin Anaesthesiol 2026;39:245-251 (rotura uterina intraparto, manejo anestésico; solo resumen); Deshmukh U et al. Am J Obstet Gynecol 2024;230:S783-S803 (trabajo de parto tras cesárea y rotura uterina; solo resumen); " + CHE)

Q(75, "Signo neurológico del déficit de líquido extracelular", "Líquidos y electrolitos",
  'El déficit de volumen del líquido extracelular se manifiesta por signos que se agrupan por aparatos. En el sistema nervioso central aparecen apatía, somnolencia, letargo, confusión y, en los casos graves, estupor y coma, por hipoperfusión cerebral y, si hay hipernatremia o hiperosmolaridad, por deshidratación celular. En el sistema cardiovascular, hay taquicardia, hipotensión (sobre todo ortostática), pulso débil y venas planas. En la piel y las mucosas se ven turgencia disminuida, lengua seca y ojos hundidos. En la termorregulación puede haber frialdad periférica, no fiebre. De las opciones, la somnolencia es el signo neurológico; la hipotensión y el pulso débil son signos cardiovasculares, la lengua seca es mucocutánea y la hipotermia leve no es un signo específico. La guía británica de 2023 sobre el estado hiperosmolar hiperglucémico recuerda que la afectación cognitiva se asocia con deshidratación pero no es específica, que es más común cuando la osmolalidad supera 330 mOsm/kg, y que el paciente puede no parecer tan deshidratado como está. El tratamiento es la reposición de líquidos adecuada al tipo de pérdida, con cristaloides isotónicos como primera elección, y la corrección lenta del sodio. Perla: ante un paciente somnoliento con sed, piense en hipovolemia o hiperosmolaridad antes de atribuirlo a sedantes.',
  "Mustafa OG et al. Diabet Med 2023;40:e15005 (guía británica del estado hiperosmolar hiperglucémico; texto completo); " + MIL + "; " + GUY)
